par = {2: 1, 3: 1, 4: 2, 5: 2, 6: 4, 7: 4, 8: 6, 9: 3}
def chain(v):
    out = [v]
    while v in par: v = par[v]; out.append(v)
    return out
def lca(a, b):
    A = chain(a)
    return next(x for x in chain(b) if x in A)
depth = lambda v: len(chain(v)) - 1
result = lca(8, 5)

